 this.page=page;this.worker=worker;InitializeComponent();foreach(var list in new[]{queue,found,issues,templates})list.DisplayMemberPath="Label";Build();Loaded+=async(_,_)=>{Localizer.Apply(this,Localizer.Language);await Run(RefreshAll);if(Environment.GetCommandLineArgs().Contains("--smoke-hub")){for(int i=0;i<Tabs.Items.Count;i++){Tabs.SelectedIndex=i;SmokeCapture.Save(this,"hub-ui",$"tab-{i}.png");}Close();}};Closing+=(_,_)=>work?.Cancel();
