 async Task Run(Func<Task> action){if(busy)return;busy=true;work=new();Tabs.IsEnabled=false;try{Status.Text="";await action();if(string.IsNullOrWhiteSpace(Status.Text))Status.Text=T("Готово");}catch(OperationCanceledException){Status.Text=T("Обробку зупинено.");}catch(Exception e){Status.Text=T(e.Message);SmokeCapture.Fail(e);}finally{Tabs.IsEnabled=true;work.Dispose();work=null;busy=false;}}
 static StackPanel Stack()=>new(){Margin=new Thickness(8)};
 void Button(Panel p,string label,Func<Task> action){var b=new Button{Content=T(label),Margin=new Thickness(0,3,6,3),Padding=new Thickness(10,5,10,5),HorizontalAlignment=HorizontalAlignment.Left};b.Click+=async(_,_)=>await Run(action);p.Children.Add(b);}
 void Label(Panel p,string s)=>p.Children.Add(new TextBlock{Text=T(s),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,6,0,3)});
 void Tab(string label,UIElement content)=>Tabs.Items.Add(new TabItem{Header=T(label),Content=content});
 void Open(JsonObject? item){if(item==null)return;SelectedPageId=item["page"]?.ToString()??item["left"]?.ToString();SelectedRecordId=item["record"]?.ToString()??item["id"]?.ToString();if(SelectedPageId!=null)Close();}
 static BitmapImage Bitmap(string path){var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.UriSource=new Uri(path);image.EndInit();image.Freeze();return image;}
 void Build()
 {
 var photo=new DockPanel();var settings=Stack();DockPanel.SetDock(settings,Dock.Top);Label(settings,"Копії для перегляду. Оригінали, записи та розпізнаний текст залишаються без змін.");var controls=new WrapPanel();settings.Children.Add(controls);foreach(var pair in new[]{("original","Оригінал"),("contrast","Контраст"),("binary","Чорно-біле"),("lighting","Освітлення")})mode.Items.Add(new ComboBoxItem{Tag=pair.Item1,Content=T(pair.Item2)});mode.SelectedIndex=1;mode.Width=160;controls.Children.Add(mode);controls.Children.Add(new TextBlock{Text=T("Поворот, градуси"),Margin=new Thickness(8)});angle.Width=65;controls.Children.Add(angle);Button(controls,"Показати обробку",RefreshPhoto);photo.Children.Add(settings);var photos=new Grid();photos.ColumnDefinitions.Add(new());photos.ColumnDefinitions.Add(new());var left=new ScrollViewer{Content=new GroupBox{Header=T("Оригінал"),Content=original},HorizontalScrollBarVisibility=ScrollBarVisibility.Auto};var right=new ScrollViewer{Content=new GroupBox{Header=T("Оброблене зображення"),Content=processed},HorizontalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetColumn(right,1);photos.Children.Add(left);photos.Children.Add(right);photo.Children.Add(photos);Tab("Фотографія",photo);
 var review=Stack();Label(review,"Розбіжності з уже збережених порівнянь. Поле невідоме, доки його не прив’язано в розмітці або не вказано вручну.");Button(review,"Оновити чергу",RefreshQueue);queue.Height=200;review.Children.Add(queue);review.Children.Add(alternatives);var opts=new WrapPanel();foreach(var n in Enumerable.Range(0,4))priority.Items.Add(n.ToString());priority.SelectedIndex=0;priority.Width=80;opts.Children.Add(priority);foreach(var pair in new[]{("unknown","Невизначене поле"),("person","Ім’я"),("date","Дата"),("house","Номер будинку"),("related1","Родич 1 як у записі"),("related2","Родич 2 як у записі")})field.Items.Add(new ComboBoxItem{Tag=pair.Item1,Content=T(pair.Item2)});field.SelectedIndex=0;opts.Children.Add(field);review.Children.Add(opts);Label(review,"Примітка до перевірки");review.Children.Add(note);review.Children.Add(done);Button(review,"Зберегти пріоритет",SaveReview);Button(review,"Відкрити джерело",()=>{Open(selectedReview);return Task.CompletedTask;});queue.SelectionChanged+=(_,_)=>{if(queue.SelectedItem is not GenealogyRow r)return;selectedReview=r.Data;alternatives.Text=string.Join("\n\n",r.Data["results"]!.AsObject().Select(x=>x.Key+": "+(x.Value?["text"]??x.Value?["error"])))+"\n"+r.Data["error"];priority.SelectedIndex=r.Data["priority"]!.GetValue<int>();note.Text=r.Data["note"]?.ToString();done.IsChecked=r.Data["done"]!.GetValue<bool>();field.SelectedItem=field.Items.Cast<ComboBoxItem>().First(x=>x.Tag.ToString()==r.Data["field"]!.ToString());};Tab("Перевірка",new ScrollViewer{Content=review});
 var search=Stack();Label(search,"Пошук у збережених полях. Збіги не створюють родинних зв’язків. Часткові збіги показують відмінності.");var fields=new WrapPanel();foreach(var pair in new[]{("person","Ім’я"),("place","Населений пункт"),("house","Номер будинку"),("year_from","Рік від"),("year_to","Рік до"),("related1","Родич 1 як у записі"),("related2","Родич 2 як у записі")}){var box=Stack();Label(box,pair.Item2);var input=new TextBox{Width=180};query[pair.Item1]=input;box.Children.Add(input);fields.Children.Add(box);}search.Children.Add(fields);search.Children.Add(currentBook);search.Children.Add(differences);Button(search,"Знайти записи",Search);found.Height=330;search.Children.Add(found);Button(search,"Відкрити джерело",()=>{Open((found.SelectedItem as GenealogyRow)?.Data);return Task.CompletedTask;});Tab("Родинний пошук",new ScrollViewer{Content=search});
 var completeness=Stack();Label(completeness,"Пропуски аркушів показуються лише за ручними позначками. Кандидат дубліката потребує підтвердження. Відсутність записів не означає порожню сторінку.");Button(completeness,"Перевірити повноту книги",RefreshGaps);completeness.Children.Add(gaps);issues.Height=300;completeness.Children.Add(issues);Button(completeness,"Відкрити джерело",()=>{Open((issues.SelectedItem as GenealogyRow)?.Data);return Task.CompletedTask;});Tool(completeness,"Книги та порядок сторінок","books");Tool(completeness,"Перевірити дублікати","research");Tab("Повнота книги",new ScrollViewer{Content=completeness});
