 void Tool(Panel p,string label,string tool)=>Button(p,label,()=>{RequestedTool=tool;SelectedPageId=page;Close();return Task.CompletedTask;});
 async Task RefreshAll(){await RefreshPhoto();await RefreshQueue();await RefreshGaps();await RefreshProfile();if(queue.Items.Count>0)queue.SelectedIndex=0;}
 async Task RefreshPhoto(){if(!double.TryParse(angle.Text,out var degrees))throw new Exception(T("Неправильний кут повороту."));var a=Args();a["mode"]=((ComboBoxItem)mode.SelectedItem).Tag.ToString();a["angle"]=degrees;var r=await Call("hub_photo",a);original.Source=Bitmap(r["original"]!["path"]!.ToString());processed.Source=Bitmap(r["processed"]!["path"]!.ToString());}
 string Field(string value)=>T(value switch{"place"=>"Населений пункт","person"=>"Ім’я","date"=>"Дата","house"=>"Номер будинку","related1"=>"Родич 1 як у записі","related2"=>"Родич 2 як у записі",_=>"Невизначене поле"});
 async Task RefreshQueue(){var r=await Call("hub_queue",Args());queue.ItemsSource=r["rows"]!.AsArray().Select(n=>new GenealogyRow(n!.AsObject(),n["priority"]+" · "+Field(n["field"]!.ToString())+" · "+n["name"]+" · "+n["number"]+(n["stale"]!.GetValue<bool>()?" · "+T("Розмітка змінилася"):""))).ToList();}
 async Task SaveReview(){if(selectedReview==null)return;var a=Args();a["key"]=selectedReview["key"]!.ToString();a["signature"]=selectedReview["signature"]!.ToString();a["priority"]=priority.SelectedIndex;a["field"]=((ComboBoxItem)field.SelectedItem).Tag.ToString();a["note"]=note.Text;a["done"]=done.IsChecked==true;await Call("hub_review",a);await RefreshQueue();}
 async Task Search(){var a=Args();foreach(var pair in query)a[pair.Key]=pair.Value.Text;a["current_book"]=currentBook.IsChecked==true;a["include_differences"]=differences.IsChecked==true;var r=await Call("hub_family_search",a);found.ItemsSource=r["rows"]!.AsArray().Select(n=>new GenealogyRow(n!.AsObject(),n["name"]+" · "+n["number"]+"\n"+string.Join(" · ",n["explanation"]!.AsArray().Select(x=>Field(x!["field"]!.ToString())+": "+x["actual"]+" ["+T(x["status"]!.ToString() switch{"match"=>"Збіг","missing"=>"Не вказано","uncertain"=>"Непевно",_=>"Відмінність"})+"]")))).ToList();if(r["limited"]!.GetValue<bool>())Status.Text=T("Показано обмежену вибірку. Уточніть пошук.");}
 async Task RefreshGaps(){var r=await Call("hub_gaps",Args());var labels=new Dictionary<string,string>{{"pages","Сторінок"},{"explicit_gaps","Позначених пропусків"},{"pending","Очікують обробки"},{"running","Обробляються"},{"errors","Збоїв"},{"recognized","Розпізнано"},{"records","Записів"},{"unverified_records","Неперевірених записів"},{"pages_without_records","Сторінок без записів"},{"duplicate_candidates","Кандидатів у дублікати"},{"confirmed_duplicates","Підтверджених дублікатів"},{"related_fragments","Споріднених фрагментів"},{"indexed_pages","Сторінок з відбитками"}};gaps.Text=r["book"]+"\n"+string.Join(" · ",r["counts"]!.AsObject().Select(x=>T(labels.GetValueOrDefault(x.Key,x.Key))+": "+x.Value));issues.ItemsSource=r["issues"]!.AsArray().Select(n=>new GenealogyRow(n!.AsObject(),n["name"]+" · "+n["number"]+" · "+n["label"]+" · "+T(n["kind"]!.ToString() switch{"missing_folio"=>"Позначений пропуск","pending"=>"Очікують обробки","running"=>"Обробляються",_=>"Збоїв"})+" · "+n["note"])).Concat(r["duplicates"]!.AsArray().Select(n=>new GenealogyRow(n!.AsObject(),n["left_name"]+" · "+n["left_number"]+" ↔ "+n["right_name"]+" · "+n["right_number"]+" · "+T(n["status"]!.ToString() switch{"confirmed_full"=>"Підтверджених дублікатів","related_fragment"=>"Споріднених фрагментів",_=>"Кандидатів у дублікати"})))).ToList();}
 async Task RefreshProfile(){var r=(await Call("hub_profile",Args())).AsObject();profileData=r;profile.Text=T("Колонок на цій сторінці")+": "+r["current_page_columns"]+"\n"+string.Join(" · ",r["profile"]!.AsObject().Select(x=>T(x.Key switch{"languages"=>"Мови","years"=>"Роки","script"=>"Письмо","layout"=>"Структура","model"=>"Модель","notes"=>"Примітки","split"=>"Роль у наборі","calendar"=>"Календар",_=>x.Key})+": "+x.Value));templates.ItemsSource=r["templates"]!.AsArray().Select(n=>new GenealogyRow(n!.AsObject(),n["name"]!.ToString())).ToList();words.ItemsSource=r["dictionary"]!.AsArray().Select(n=>n!["term"]+" · "+n["meaning"]).ToList();}
 async Task ApplyColumnTemplate(){if(templates.SelectedItem is not GenealogyRow row)return;var a=Args();a["template"]=row.Data["id"]!.ToString();a["pages"]=new JsonArray(page);await Call("template_apply",a);await RefreshProfile();}
 async Task ApplyBook(){var id=profileData?["book"]?["id"]?.ToString();if(id==null)throw new Exception(T("Спочатку об’єднайте фото в книгу."));await Call("book_template",new(){["book"]=id,["apply"]=true,["pages"]=new JsonArray(page)});await RefreshProfile();}
